component.componentCode:
"use client"

// AsciiArt — "HANZO Fire Alarm Code", made with the 21st ASCII editor and baked
// to its exact rendered output (looping video + poster). Zero dependencies:
// one <video> that fills its parent. Drop it behind or inside your content:
// <div className="relative h-96"><AsciiArt className="absolute inset-0" /></div>
// Remix the source recipe (styles, animation, palette) in the editor:
// https://21st.dev/community/ascii/editor?from=025c90a5-8f5c-4e0b-88e6-3484b122a641
export function AsciiArt({ className }: { className?: string }) {
  return (
    <video
      className={className}
      src={"https://assets.21st.dev/ascii-recipes/videos/user_3GPGUGW0kezwI1M261bFhugwynL/02e64973-395f-4a38-9085-0e9ca2ceb3dc.mp4"}
      poster={"https://assets.21st.dev/ascii-recipes/thumbnails/user_3GPGUGW0kezwI1M261bFhugwynL/dcca5922-95d6-4455-b426-bf68f87a3b67.webp"}
      autoPlay
      loop
      muted
      playsInline
      aria-label={"HANZO Fire Alarm Code — animated ASCII art"}
      style={{
        display: "block",
        width: "100%",
        height: "100%",
        objectFit: "cover",
      }}
    />
  )
}

